from PIL import Image
import numpy as np
im=np.asarray(Image.open('first_frame.png').convert('RGB')).astype(np.int16)
# inspect color separability against local wall
for y in [8,12,16,20,24,28,32,36,40,44,48]:
    row=[]
    for x in range(108,152,2):
        r,g,b=im[y,x]
        if b-r>20 and g-r>5: row.append('B')
        elif r+g+b<250: row.append('K')
        elif g-r>20: row.append('G')
        elif abs(int(b)-int(r))<12 and r>75: row.append('.')
        else: row.append(' ')
    print(f'{y:02d} '+''.join(row))
