/bin/bash -c "python - <<'PY'
from PIL import Image
import numpy as np
im=np.asarray(Image.open('first_frame.png').convert('RGB'))
for y in [17,18,19,20,21,22,24,26,28,30,32,34,36,38,40,42,44,46,48,50,52,54]:
 # spans of non-wall based on blue/dark threshold, x 110-154
 vals=[]
 for x in range(108,155):
  r,g,b=im[y,x].astype(int)
  if (b-r>15 and b>60) or (r+g+b<280): vals.append(x)
 # group
 groups=[]
 for x in vals:
  if not groups or x>groups[-1][-1]+1: groups.append([x])
  else: groups[-1].append(x)
 print(y,[(g[0],g[-1]) for g in groups])
